(()=>{
const suppliers={studio:{name:'Studio Merch',contact:'Aarav',email:'aarav@studio-merch.example'},gather:{name:'Gather Events',contact:'Meera',email:'meera@gather-events.example'},room:{name:'Room & Co.',contact:'Kabir',email:'kabir@room-co.example'}};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const host=document.getElementById('enquiry-root');let opener;let supplierId;let stored={};try{stored=JSON.parse(localStorage.getItem('quotelens-enquiries-v1')||'{}')}catch{}
function close(){host.innerHTML='';opener?.focus()}
function message(text){const el=document.getElementById('enquiry-status');el.textContent=text;el.hidden=false;setTimeout(()=>el.hidden=true,4000)}
function open(id){supplierId=id;opener=document.activeElement;const s=suppliers[id],v=stored[id]?.values||{};host.innerHTML=`<div class="modal-overlay"><section class="modal enquiry-modal" role="dialog" aria-modal="true" aria-labelledby="enquiry-title"><div class="modal-head"><div><span class="eyebrow">START A CONVERSATION</span><h2 id="enquiry-title">A brief for ${s.name}.</h2></div><button class="close-button" data-enquiry-close aria-label="Close enquiry">×</button></div><p class="enquiry-note">Prepare a quotation request for ${s.contact}. This is an illustrative profile; nothing will be sent.</p><form id="enquiry-form"><div class="field-row"><div class="field"><label for="enq-name">Your name / organisation</label><input id="enq-name" name="name" value="${escape(v.name)}" required></div><div class="field"><label for="enq-email">Reply email</label><input id="enq-email" type="email" name="email" value="${escape(v.email)}" required></div></div><div class="field"><label for="enq-brief">What do you need?</label><textarea id="enq-brief" name="brief" placeholder="Scope, quantity, location, and your must-haves…" required>${escape(v.brief)}</textarea></div><div class="field-row"><div class="field"><label for="enq-date">Required by</label><input id="enq-date" name="date" type="date" value="${escape(v.date)}"></div><div class="field"><label for="enq-budget">Budget to share (optional)</label><input id="enq-budget" name="budget" placeholder="e.g. ₹30,000–₹35,000" value="${escape(v.budget)}"></div></div><button class="button primary small" type="submit">Prepare quotation request →</button></form><div id="enquiry-result" hidden></div></section></div>`;host.querySelector('[data-enquiry-close]').focus();host.querySelector('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget));const body=`Hi ${s.contact},\n\nI’m enquiring on behalf of ${v.name}.\n\n${v.brief}\n${v.date?'\nRequired by: '+v.date:''}${v.budget?'\nBudget shared: '+v.budget:''}\n\nPlease send an itemised quotation, including taxes, delivery, timelines, payment terms, and any exclusions, to ${v.email}.\n\nRegards,\n${v.name}`;stored[id]={values:v,body};let saved=true;try{localStorage.setItem('quotelens-enquiries-v1',JSON.stringify(stored))}catch{saved=false}host.querySelector('#enquiry-form').hidden=true;const r=host.querySelector('#enquiry-result');r.hidden=false;r.innerHTML=`<span class="chip gold">Request prepared · Not sent</span><p>To ${s.contact} · ${s.email}</p><label class="visually-hidden" for="enquiry-body">Prepared quotation request</label><textarea id="enquiry-body" class="email-body">${escape(body)}</textarea><div class="form-footer"><button class="button small" type="button" data-enquiry-back>Edit requirements</button><button class="button primary small" type="button" data-enquiry-copy>Copy request</button></div><p class="small-muted">${saved?'Saved locally so you can return to this enquiry.':'Storage unavailable; copy the request to keep it.'} Real profiles and email delivery will be connected when the directory launches.</p>`;r.querySelector('[data-enquiry-back]').addEventListener('click',()=>{r.hidden=true;host.querySelector('#enquiry-form').hidden=false});r.querySelector('[data-enquiry-copy]').addEventListener('click',async()=>{const body=r.querySelector('textarea').value;stored[id].body=body;try{localStorage.setItem('quotelens-enquiries-v1',JSON.stringify(stored))}catch{}try{await navigator.clipboard.writeText(body);message('Quotation request copied.')}catch{r.querySelector('textarea').select();message('Select and copy the request manually.')}})});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter){document.querySelectorAll('[data-filter]').forEach(x=>{const yes=x===b;x.classList.toggle('active',yes);x.setAttribute('aria-pressed',String(yes))});document.querySelectorAll('.partner-card').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)}if(b.dataset.enquire)open(b.dataset.enquire);if(b.hasAttribute('data-enquiry-close'))close()});
document.addEventListener('keydown',e=>{const modal=host.querySelector('.modal');if(!modal)return;if(e.key==='Escape')close();if(e.key==='Tab'){const f=[...modal.querySelectorAll('button,input,textarea')].filter(x=>!x.closest('[hidden]'));if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}});
})();
